import type { GenerationResponseMessage, Status, Turn } from '@proton/lumo-api-client/core/types';
import { Role } from '@proton/lumo-api-client/core/types';

import { getByokConfig, isByokEnabled, type ByokConfig } from './byokConfig';

/**
 * OpenAI-compatible BYOK client.
 *
 * Talks the standard chat completions wire format (/chat/completions, SSE
 * streaming) against any provider, and adapts the response into the same
 * GenerationResponseMessage stream that LumoApiClient.callAssistant emits,
 * so the app's Redux integration works unchanged.
 *
 * Cross-origin providers are reached through a same-origin proxy at
 * `/byok-api/*` carrying the upstream base URL in the `X-Byok-Target`
 * header (providers don't send CORS headers). Relative base URLs (e.g.
 * `/v1` pointing at a gateway on this origin) are called directly.
 */

const PROXY_PREFIX = '/byok-api';

type OpenAiContentPart = { type: 'text'; text: string } | { type: 'image_url'; image_url: { url: string } };

interface OpenAiMessage {
    role: 'system' | 'user' | 'assistant';
    content: string | OpenAiContentPart[];
}

interface ByokDelta {
    content?: string;
    reasoning?: string;
}

export interface ByokCallAssistantOptions {
    turns: Turn[];
    chunkCallback?: (message: GenerationResponseMessage) => Promise<void> | void;
    finishCallback?: (status: Status) => Promise<void> | void;
    signal?: AbortSignal;
    generateTitle?: boolean;
}

function guessImageMime(base64: string): string {
    if (base64.startsWith('/9j/')) {
        return 'image/jpeg';
    }
    if (base64.startsWith('R0lGOD')) {
        return 'image/gif';
    }
    if (base64.startsWith('UklGR')) {
        return 'image/webp';
    }
    return 'image/png';
}

/**
 * Convert Lumo wire turns into OpenAI chat messages. Lumo-internal tool
 * turns (from Proton-server tooling) are flattened to text markers so the
 * conversation context survives, and unencrypted images become image_url
 * content parts. Encrypted images (U2L) cannot be decrypted client-side
 * here and are skipped.
 */
export function convertTurnsToOpenAiMessages(turns: Turn[]): OpenAiMessage[] {
    const messages: OpenAiMessage[] = [];

    for (const turn of turns) {
        const content = turn.content ?? '';

        switch (turn.role) {
            case Role.System:
                if (content) {
                    messages.push({ role: 'system', content });
                }
                break;

            case Role.User: {
                const images = (turn.images ?? []).filter((img) => !img.encrypted && img.data);
                if (images.length === 0) {
                    messages.push({ role: 'user', content });
                    break;
                }
                const parts: OpenAiContentPart[] = [];
                if (content) {
                    parts.push({ type: 'text', text: content });
                }
                for (const img of images) {
                    parts.push({ type: 'image_url', image_url: { url: `data:${guessImageMime(img.data)};base64,${img.data}` } });
                }
                messages.push({ role: 'user', content: parts });
                break;
            }

            case Role.Assistant:
                messages.push({ role: 'assistant', content });
                break;

            case Role.ToolCall:
                messages.push({ role: 'assistant', content: `[Tool call: ${content}]` });
                break;

            case Role.ToolResult:
                messages.push({ role: 'user', content: `[Tool result: ${content}]` });
                break;
        }
    }

    return messages;
}

function resolveRequestRouting(config: ByokConfig, suffix: string): { url: string; headers: Record<string, string> } {
    const base = config.baseUrl.trim().replace(/\/+$/, '');
    if (base.startsWith('/')) {
        // Same-origin gateway: call directly, no proxy needed.
        return { url: `${base}${suffix}`, headers: {} };
    }
    // Cross-origin provider: go through the same-origin /byok-api proxy.
    return { url: `${PROXY_PREFIX}${suffix}`, headers: { 'X-Byok-Target': base } };
}

async function byokFetch(config: ByokConfig, suffix: string, init: RequestInit = {}): Promise<Response> {
    const { url, headers: routingHeaders } = resolveRequestRouting(config, suffix);
    return fetch(url, {
        ...init,
        headers: {
            ...routingHeaders,
            'Content-Type': 'application/json',
            Authorization: `Bearer ${config.apiKey}`,
            ...(init.headers ?? {}),
        },
        signal: init.signal,
    });
}

async function throwByokError(response: Response, context: string): Promise<never> {
    let detail = response.statusText;
    try {
        const json = await response.json();
        detail = json?.error?.message ?? json?.message ?? json?.detail ?? JSON.stringify(json).slice(0, 300);
    } catch {
        // not JSON — keep statusText
    }
    throw new Error(`${context} failed (HTTP ${response.status}): ${detail}`);
}

function buildRequestBody(config: ByokConfig, messages: OpenAiMessage[], stream: boolean): string {
    const body: Record<string, unknown> = {
        model: config.model,
        messages,
        stream,
    };
    if (config.disableThinking) {
        // NVIDIA NIM nemotron models: disable inline chain-of-thought.
        body.chat_template_kwargs = { thinking: false };
    }
    return JSON.stringify(body);
}

function extractDeltaText(delta: any): ByokDelta {
    const result: ByokDelta = {};
    const rawContent = delta?.content;
    if (typeof rawContent === 'string') {
        result.content = rawContent;
    } else if (Array.isArray(rawContent)) {
        const text = rawContent
            .map((part: any) => (typeof part === 'string' ? part : part?.text ?? ''))
            .join('');
        if (text) {
            result.content = text;
        }
    }
    const reasoning = delta?.reasoning_content ?? delta?.reasoning;
    if (typeof reasoning === 'string' && reasoning) {
        result.reasoning = reasoning;
    }
    return result;
}

/**
 * Parse an OpenAI SSE stream into content/reasoning deltas.
 */
async function* streamByokDeltas(response: Response, signal?: AbortSignal): AsyncGenerator<ByokDelta> {
    const reader = response.body!.getReader();
    const decoder = new TextDecoder();
    let buffer = '';

    try {
        while (true) {
            if (signal?.aborted) {
                throw new DOMException('Aborted', 'AbortError');
            }
            const { done, value } = await reader.read();
            if (done) {
                break;
            }
            buffer += decoder.decode(value, { stream: true });

            let newlineIndex: number;
            while ((newlineIndex = buffer.indexOf('\n')) !== -1) {
                const line = buffer.slice(0, newlineIndex).trim();
                buffer = buffer.slice(newlineIndex + 1);
                if (!line.startsWith('data:')) {
                    continue;
                }
                const data = line.slice(5).trim();
                if (!data || data === '[DONE]') {
                    continue;
                }
                try {
                    const parsed = JSON.parse(data);
                    if (parsed?.error) {
                        throw new Error(parsed.error.message ?? 'Provider returned an error mid-stream');
                    }
                    const delta = parsed?.choices?.[0]?.delta;
                    if (!delta) {
                        continue;
                    }
                    const extracted = extractDeltaText(delta);
                    if (extracted.content || extracted.reasoning) {
                        yield extracted;
                    }
                } catch (parseError) {
                    if (parseError instanceof SyntaxError) {
                        continue; // tolerate malformed lines
                    }
                    throw parseError;
                }
            }
        }
    } finally {
        reader.releaseLock();
    }
}

/** Short conversation title from the first user turn(s). */
function extractTitleSource(turns: Turn[]): string | null {
    const userContent = turns
        .filter((turn) => turn.role === Role.User && turn.content && !turn.content.startsWith('<lumo-image'))
        .map((turn) => turn.content!.trim())
        .filter(Boolean);
    if (userContent.length === 0) {
        return null;
    }
    const text = userContent.join('\n');
    return text.length > 120 ? `${text.slice(0, 120)}…` : text;
}

function cleanTitle(raw: string): string {
    let title = raw.trim();
    const quoted = title.match(/"([^"]+)"/);
    if (quoted) {
        title = quoted[1].trim();
    }
    title = title.replace(/\s+/g, ' ');
    while (title.endsWith('.') || title.endsWith(':') || title.endsWith('—') || title.endsWith('-')) {
        title = title.slice(0, -1).trim();
    }
    if (title.length > 60) {
        title = `${title.slice(0, 60).trimEnd()}…`;
    }
    return title;
}

const TITLE_SYSTEM_PROMPT =
    'Generate a very short conversation title (3 to 6 words) summarizing the user message. ' +
    'Reply with the title only — no quotes, no punctuation at the end, no explanation.';

async function runTitleGeneration(
    config: ByokConfig,
    turns: Turn[],
    chunkCallback: ByokCallAssistantOptions['chunkCallback'],
    signal?: AbortSignal
): Promise<void> {
    try {
        const source = extractTitleSource(turns);
        if (!source || !chunkCallback) {
            return;
        }
        const messages: OpenAiMessage[] = [
            { role: 'system', content: TITLE_SYSTEM_PROMPT },
            { role: 'user', content: source },
        ];
        const response = await byokFetch(config, '/chat/completions', {
            method: 'POST',
            body: buildRequestBody(config, messages, false),
            signal,
        });
        if (!response.ok) {
            await throwByokError(response, 'Title generation');
        }
        const json = await response.json();
        const raw = json?.choices?.[0]?.message?.content;
        const title = cleanTitle(typeof raw === 'string' ? raw : '');
        if (!title) {
            return;
        }
        await chunkCallback({ type: 'ingesting', target: 'title' });
        await chunkCallback({ type: 'token_data', target: 'title', count: 0, content: title });
    } catch (error: any) {
        if (error?.name !== 'AbortError') {
            // Non-critical: the conversation falls back to the default untitled state.
            console.warn('[BYOK] Title generation failed:', error);
        }
    }
}

/**
 * BYOK equivalent of LumoApiClient.callAssistant for text chat. Emits the same
 * chunk sequence (ingesting/token_data per target, done) and calls
 * finishCallback with the final status. Streaming errors are surfaced by
 * emitting an 'error' chunk (which the app's error handler turns into UI
 * state), mirroring the Proton stream behavior.
 */
export async function byokCallAssistant(options: ByokCallAssistantOptions): Promise<void> {
    const config = getByokConfig();
    const { turns, chunkCallback, finishCallback, signal, generateTitle = false } = options;

    let finalStatus: Status = 'failed';

    try {
        const tasks: Promise<void>[] = [runMainGeneration(config, turns, chunkCallback, signal)];

        if (generateTitle) {
            tasks.push(runTitleGeneration(config, turns, chunkCallback, signal));
        }

        await Promise.all(tasks);
        finalStatus = 'succeeded';
        await chunkCallback?.({ type: 'done' });
    } catch (error: any) {
        if (error?.name === 'AbortError') {
            // Stopped generation: finish gracefully with the partial content,
            // matching LumoApiClient behavior.
            finalStatus = 'succeeded';
            await chunkCallback?.({ type: 'done' });
        } else {
            console.error('[BYOK] Generation failed:', error);
            // Surface the failure through the standard error chunk so the
            // app's errorHandler / UI error state kicks in. This call throws
            // when an errorHandler is installed, mirroring Proton's stream.
            await chunkCallback?.({ type: 'error' });
        }
    } finally {
        await finishCallback?.(finalStatus);
    }
}

async function runMainGeneration(
    config: ByokConfig,
    turns: Turn[],
    chunkCallback: ByokCallAssistantOptions['chunkCallback'],
    signal?: AbortSignal
): Promise<void> {
    const messages = convertTurnsToOpenAiMessages(turns);
    const response = await byokFetch(config, '/chat/completions', {
        method: 'POST',
        body: buildRequestBody(config, messages, true),
        signal,
    });
    if (!response.ok) {
        await throwByokError(response, 'Generation');
    }
    if (!response.body) {
        throw new Error('Provider returned an empty response body');
    }

    await chunkCallback?.({ type: 'ingesting', target: 'message' });

    let messageCount = 0;
    let reasoningCount = 0;
    let emittedAny = false;

    for await (const delta of streamByokDeltas(response, signal)) {
        emittedAny = true;
        if (delta.reasoning) {
            await chunkCallback?.({
                type: 'token_data',
                target: 'reasoning',
                count: reasoningCount++,
                content: delta.reasoning,
            });
        }
        if (delta.content) {
            await chunkCallback?.({
                type: 'token_data',
                target: 'message',
                count: messageCount++,
                content: delta.content,
            });
        }
    }

    if (!emittedAny) {
        throw new Error('Provider returned an empty stream');
    }
}

/**
 * BYOK equivalent of quickChat: one-shot completion returning the full text.
 */
export async function byokQuickChat(
    message: string,
    { signal }: { signal?: AbortSignal } = {}
): Promise<string> {
    const config = getByokConfig();
    const messages: OpenAiMessage[] = [{ role: 'user', content: message }];
    const response = await byokFetch(config, '/chat/completions', {
        method: 'POST',
        body: buildRequestBody(config, messages, true),
        signal,
    });
    if (!response.ok) {
        await throwByokError(response, 'Completion');
    }
    if (!response.body) {
        throw new Error('Provider returned an empty response body');
    }

    let result = '';
    for await (const delta of streamByokDeltas(response, signal)) {
        if (delta.content) {
            result += delta.content;
        }
    }
    return result;
}

/**
 * Fetch the provider's model list (GET {base}/models).
 */
export async function byokFetchModels(config: ByokConfig): Promise<string[]> {
    const response = await byokFetch(config, '/models', { method: 'GET' });
    if (!response.ok) {
        await throwByokError(response, 'Model list');
    }
    const json = await response.json();
    const models: string[] = (json?.data ?? [])
        .map((entry: any) => entry?.id)
        .filter((id: unknown): id is string => typeof id === 'string' && id.length > 0);
    return [...new Set(models)].sort((a, b) => a.localeCompare(b));
}

/**
 * Tiny non-streaming request used by the settings "Test connection" button.
 * Returns latency and the model reply; throws with a readable message on failure.
 */
export async function byokTestConnection(config: ByokConfig): Promise<{ latencyMs: number; reply: string }> {
    const started = Date.now();
    const messages: OpenAiMessage[] = [
        { role: 'system', content: 'Reply with the single word: OK' },
        { role: 'user', content: 'ping' },
    ];
    const response = await byokFetch(config, '/chat/completions', {
        method: 'POST',
        body: JSON.stringify({
            model: config.model,
            messages,
            stream: false,
            max_tokens: 8,
            ...(config.disableThinking ? { chat_template_kwargs: { thinking: false } } : {}),
        }),
    });
    if (!response.ok) {
        await throwByokError(response, 'Test request');
    }
    const json = await response.json();
    const raw = json?.choices?.[0]?.message?.content;
    const reply = (typeof raw === 'string' ? raw : '').trim();
    return { latencyMs: Date.now() - started, reply };
}

export { isByokEnabled };
