const LumoLogo = ({ variant = 'with-wordmark', hasTitle = true, className, size, ...rest }: LogoProps) => {
    const [uid] = useState(generateUID('logo'));

    if (variant === 'glyph-only') {
        return (
            <img
                src={lumoCatIcon}
                alt={hasTitle ? LUMO_APP_NAME : ''}
                aria-hidden={!hasTitle}
                className={clsx('logo', 'glyph-only', size && `icon-size-${size}`, className)}
            />
        );
    }

    return (
        <LogoBase
            uid={uid}
            logoWidth={WORDMARK_WIDTH}
            logoHeight={WORDMARK_HEIGHT}
            viewBox={`0 0 ${WORDMARK_WIDTH} ${WORDMARK_HEIGHT}`}
            title={hasTitle ? LUMO_APP_NAME : undefined}
            variant={variant}
            className={className}
            {...rest}
        >
            <LumoCatMark />
            <LumoWordmarkText />
        </LogoBase>
    );
};

export default LumoLogo;
