import { useEffect, useState } from 'react';

import type { ByokConfig } from './byokTypes';

export type { ByokConfig };

const STORAGE_KEY = 'lumo.byok.config.v1';
const CHANGE_EVENT = 'lumo-byok-config-changed';

/**
 * Default BYOK provider. Requests are routed through the same-origin
 * `/byok-api` proxy (see byokClient), so no CORS is involved.
 */
export const BYOK_DEFAULTS: ByokConfig = {
    enabled: true,
    baseUrl: 'https://integrate.api.nvidia.com/v1',
    apiKey: '',
    model: '',
    disableThinking: true,
};

function sanitize(raw: unknown): Partial<ByokConfig> {
    if (!raw || typeof raw !== 'object') {
        return {};
    }
    const input = raw as Record<string, unknown>;
    const result: Partial<ByokConfig> = {};
    if (typeof input.enabled === 'boolean') {
        result.enabled = input.enabled;
    }
    if (typeof input.baseUrl === 'string' && input.baseUrl.trim()) {
        result.baseUrl = input.baseUrl.trim();
    }
    if (typeof input.apiKey === 'string') {
        result.apiKey = input.apiKey;
    }
    if (typeof input.model === 'string' && input.model.trim()) {
        result.model = input.model.trim();
    }
    if (typeof input.disableThinking === 'boolean') {
        result.disableThinking = input.disableThinking;
    }
    return result;
}

function readConfig(): ByokConfig {
    try {
        const stored = window.localStorage.getItem(STORAGE_KEY);
        return {
            ...BYOK_DEFAULTS,
            ...(stored ? sanitize(JSON.parse(stored)) : {}),
        };
    } catch {
        return { ...BYOK_DEFAULTS };
    }
}

export function getByokConfig(): ByokConfig {
    return readConfig();
}

export function isByokEnabled(): boolean {
    return readConfig().enabled;
}

export function setByokConfig(patch: Partial<ByokConfig>): ByokConfig {
    const next = { ...readConfig(), ...patch };
    try {
        window.localStorage.setItem(STORAGE_KEY, JSON.stringify(next));
    } catch {
        // storage unavailable (private mode etc.) — keep in-memory only
    }
    snapshot = next;
    window.dispatchEvent(new CustomEvent(CHANGE_EVENT));
    return next;
}

export function resetByokConfig(): ByokConfig {
    return setByokConfig(BYOK_DEFAULTS);
}

// useSyncExternalStore plumbing: keep a cached snapshot so getSnapshot is stable
let snapshot: ByokConfig | null = null;

function getSnapshot(): ByokConfig {
    if (!snapshot) {
        snapshot = readConfig();
    }
    return snapshot;
}

function subscribe(listener: () => void): () => void {
    window.addEventListener(CHANGE_EVENT, listener);
    window.addEventListener('storage', listener);
    return () => {
        window.removeEventListener(CHANGE_EVENT, listener);
        window.removeEventListener('storage', listener);
    };
}

/**
 * React binding for the BYOK config. Re-renders on any config change.
 */
export function useByokConfig(): [ByokConfig, (patch: Partial<ByokConfig>) => void] {
    const [, forceUpdate] = useState(0);

    useEffect(() => {
        const listener = () => forceUpdate((n) => n + 1);
        return subscribe(listener);
    }, []);

    // Read fresh each render; the snapshot cache keeps identity stable per change.
    return [getSnapshot(), setByokConfig];
}
