import { useState, type ChangeEvent } from 'react';

import { c } from 'ttag';

import { Button } from '@proton/atoms/Button/Button';
import { InputFieldTwo } from '@proton/components/index';
import { Toggle } from '@proton/components/index';

import { byokFetchModels, byokTestConnection } from '../../../lib/byok/byokClient';
import { resetByokConfig, useByokConfig } from '../../../lib/byok/byokConfig';
import { LumoIcon } from '../../LumoIcon/LumoIcon';
import { SettingsSectionItem } from './SettingsSectionItem';

const MAX_MODEL_CHIPS = 40;

const ByokPanel = () => {
    const [config, update] = useByokConfig();
    const [testing, setTesting] = useState(false);
    const [testResult, setTestResult] = useState<{ ok: boolean; text: string } | null>(null);
    const [loadingModels, setLoadingModels] = useState(false);
    const [models, setModels] = useState<string[]>([]);
    const [modelsError, setModelsError] = useState<string | null>(null);

    const handleTest = async () => {
        setTesting(true);
        setTestResult(null);
        try {
            const { latencyMs, reply } = await byokTestConnection(config);
            setTestResult({
                ok: true,
                text: c('collider_2025: Info').t`Connected in ${latencyMs}ms — model replied: ${reply || '(empty)'}`,
            });
        } catch (error: any) {
            setTestResult({ ok: false, text: error?.message ?? String(error) });
        } finally {
            setTesting(false);
        }
    };

    const handleFetchModels = async () => {
        setLoadingModels(true);
        setModelsError(null);
        try {
            const list = await byokFetchModels(config);
            setModels(list);
            if (list.length === 0) {
                setModelsError(c('collider_2025: Error').t`Provider returned no models`);
            }
        } catch (error: any) {
            setModels([]);
            setModelsError(error?.message ?? String(error));
        } finally {
            setLoadingModels(false);
        }
    };

    return (
        <div className="flex flex-column flex-nowrap *:min-size-auto gap-4">
            <SettingsSectionItem
                icon="Cpu"
                text={c('collider_2025: Title').t`Custom AI provider (BYOK)`}
                subtext={c('collider_2025: Description')
                    .t`Route chats through your own OpenAI-compatible provider instead of Proton's Lumo backend. Requests go through this server's /byok-api proxy.`}
                button={
                    <Toggle
                        id="byok-enabled-toggle"
                        checked={config.enabled}
                        onChange={() => update({ enabled: !config.enabled })}
                    />
                }
            />

            {config.enabled && (
                <>
                    <InputFieldTwo
                        id="byok-base-url"
                        label={c('collider_2025: Label').t`Base URL`}
                        placeholder="https://integrate.api.nvidia.com/v1"
                        value={config.baseUrl}
                        onChange={(event: ChangeEvent<HTMLInputElement>) => update({ baseUrl: event.target.value })}
                        hint={c('collider_2025: Hint')
                            .t`OpenAI-compatible base URL. Chat completions endpoint: <base>/chat/completions`}
                        assistContainerClassName="hidden"
                    />

                    <InputFieldTwo
                        id="byok-api-key"
                        label={c('collider_2025: Label').t`API key`}
                        type="password"
                        value={config.apiKey}
                        onChange={(event: ChangeEvent<HTMLInputElement>) => update({ apiKey: event.target.value })}
                        placeholder="sk-… / nvapi-…"
                    />

                    <div className="flex flex-row flex-nowrap items-end gap-2 w-full">
                        <InputFieldTwo
                            id="byok-model"
                            label={c('collider_2025: Label').t`Model`}
                            value={config.model}
                            onChange={(event: ChangeEvent<HTMLInputElement>) => update({ model: event.target.value })}
                            placeholder="provider/model-id"
                            className="flex-1"
                        />
                        <Button
                            shape="outline"
                            className="mb-2 shrink-0"
                            onClick={handleFetchModels}
                            loading={loadingModels}
                            disabled={!config.baseUrl || !config.apiKey}
                        >
                            {c('collider_2025: Action').t`Fetch models`}
                        </Button>
                    </div>

                    {modelsError && <span className="color-danger text-sm">{modelsError}</span>}

                    {models.length > 0 && (
                        <div className="flex flex-row flex-wrap gap-2">
                            {models.slice(0, MAX_MODEL_CHIPS).map((modelId) => (
                                <Button
                                    key={modelId}
                                    shape={config.model === modelId ? 'solid' : 'outline'}
                                    size="small"
                                    onClick={() => update({ model: modelId })}
                                    title={modelId}
                                >
                                    <span className="text-ellipsis inline-block max-w-full">{modelId}</span>
                                </Button>
                            ))}
                            {models.length > MAX_MODEL_CHIPS && (
                                <span className="color-weak text-sm self-center">
                                    +{models.length - MAX_MODEL_CHIPS}
                                </span>
                            )}
                        </div>
                    )}

                    <SettingsSectionItem
                        icon="ListChecks"
                        text={c('collider_2025: Title').t`API format`}
                        subtext={c('collider_2025: Description').t`Chat completions (/chat/completions), SSE streaming`}
                    />

                    <SettingsSectionItem
                        icon="BrainCircuit"
                        text={c('collider_2025: Title').t`Disable thinking mode`}
                        subtext={c('collider_2025: Description')
                            .t`Sends chat_template_kwargs with thinking disabled (NVIDIA NIM nemotron models). Turn off if your provider rejects the parameter.`}
                        button={
                            <Toggle
                                id="byok-thinking-toggle"
                                checked={config.disableThinking}
                                onChange={() => update({ disableThinking: !config.disableThinking })}
                            />
                        }
                    />

                    <div className="flex flex-row flex-nowrap items-center gap-2">
                        <Button onClick={handleTest} loading={testing} disabled={!config.baseUrl || !config.model}>
                            {c('collider_2025: Action').t`Test connection`}
                        </Button>
                        <Button shape="ghost" onClick={() => resetByokConfig()}>
                            {c('collider_2025: Action').t`Reset to defaults`}
                        </Button>
                    </div>

                    {testResult && (
                        <div className="flex flex-row items-start gap-2 rounded p-3 text-sm bg-weak">
                            <LumoIcon
                                name={testResult.ok ? 'CircleCheck' : 'CircleAlert'}
                                size={16}
                                className={testResult.ok ? 'color-success shrink-0' : 'color-danger shrink-0'}
                            />
                            <span className="text-break-anywhere">{testResult.text}</span>
                        </div>
                    )}
                </>
            )}
        </div>
    );
};

export default ByokPanel;
